// Parse RSS XML for all companies, pre-filter for executive role keywords only
const items = $input.all();
const companies = $('Fetch Active Companies').all();
const results = [];

const EXEC_KEYWORDS = [
  'cto', 'chief technology officer',
  'ciso', 'chief information security officer',
  'vp of engineering', 'vp engineering', 'vice president of engineering',
  'head of devops', 'head of engineering', 'head of infrastructure'
];

for (let i = 0; i < items.length; i++) {
  const xml = items[i].json.data || items[i].json.body || '';
  const company = companies[i]?.json || {};

  const titleRegex = /<item>\s*<title>([^<]+)<\/title>.*?<pubDate>([^<]*)<\/pubDate>/gs;
  const headlines = [];
  let match;

  while ((match = titleRegex.exec(xml)) !== null) {
    const title = match[1].replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&#39;/g, "'").replace(/&quot;/g, '"');
    const pubDate = match[2];
    const lower = title.toLowerCase();
    if (EXEC_KEYWORDS.some(kw => lower.includes(kw))) {
      headlines.push(`[${pubDate}] ${title}`);
    }
  }

  if (headlines.length > 0) {
    results.push({ json: {
      company_id: company.id,
      company_name: company.name,
      headlines: headlines.join('\n')
    }});
  }
}

return results;

// Parse AI JSON output, expand into individual candidate items
const companyData = $('Split for AI Extract').item.json;
let raw = $input.item.json.output || $input.item.json.text || '[]';

raw = raw.replace(/```json\s*/g, '').replace(/```\s*/g, '').trim();

let executives = [];
try {
  executives = JSON.parse(raw);
} catch (e) {
  // Try extracting array
  const arrMatch = raw.match(/\[.*\]/s);
  if (arrMatch) {
    try {
      executives = JSON.parse(arrMatch[0]);
    } catch (e2) {
      // JSON truncated, try fixing
      let fixed = arrMatch[0].trim();
      if (!fixed.endsWith(']')) {
        if (!fixed.endsWith('}')) fixed += '"}';
        fixed += ']';
      }
      try { executives = JSON.parse(fixed); } catch (e3) {}
    }
  }
}

if (!Array.isArray(executives) || executives.length === 0) {
  // Return empty marker to keep loop alive
  return [{ json: { _skip: true, company_id: companyData.company_id } }];
}

const results = executives.map(exec => ({
  json: {
    company_id: companyData.company_id,
    company_name: companyData.company_name,
    person_name: (exec.person_name || '').replace(/'/g, "''"),
    title: (exec.title || '').replace(/'/g, "''"),
    action: exec.action || 'appointed',
    source_title: (exec.source_title || '').replace(/'/g, "''"),
    pub_date: exec.pub_date || '',
    _skip: false
  }
})).filter(item => {
  const name = item.json.person_name.toLowerCase();
  const TITLE_WORDS = ['cto', 'ceo', 'cfo', 'cio', 'ciso', 'cpo', 'coo', 'vp ', 'vice president', 'head of', 'director', 'general counsel', 'president', 'chief'];
  const COMPANY_INDICATORS = ["'s ", "microsoft", "google", "amazon", "workday", "salesforce", "oracle", "meta", "apple", "azure"];
  if (TITLE_WORDS.some(t => name.includes(t))) return false;
  if (COMPANY_INDICATORS.some(c => name.includes(c))) return false;
  if (name.trim().split(/\s+/).length < 2) return false;
  return true;
});

if (results.length === 0) {
  return [{ json: { _skip: true, company_id: companyData.company_id } }];
}
return results;

// Parse AI enrichment output into structured data for DB updates
const items = $input.all();
const profiles = $('Insert to executive_profiles').all();

const sq = (v) => (v && typeof v === 'string') ? v.replace(/'/g, "''") : '';
const sqj = (v) => {
  try {
    const s = typeof v === 'string' ? v : JSON.stringify(v || []);
    return s.replace(/'/g, "''");
  } catch(e) { return '[]'; }
};

const results = [];
for (let i = 0; i < items.length; i++) {
  const profile = profiles[i]?.json || {};
  let raw = items[i].json.output || items[i].json.text || '{}';
  raw = raw.replace(/```json\s*/g, '').replace(/```\s*/g, '').trim();

  let parsed = {};
  try {
    parsed = JSON.parse(raw);
  } catch(e) {
    const match = raw.match(/\{[\s\S]*\}/);
    if (match) try { parsed = JSON.parse(match[0]); } catch(e2) {}
  }

  const social = parsed.social || {};
  const activities = parsed.activities || [];

  results.push({
    json: {
      id: profile.id,
      person_name: profile.person_name,
      company_name: profile.company_name,
      linkedin_url: sq(social.linkedin_url),
      linkedin_snippet: sq(social.linkedin_snippet),
      twitter_url: sq(social.twitter_url),
      github_url: sq(social.github_url),
      blog_url: sq(social.blog_url),
      enrichment_data: sqj(activities)
    }
  });
}

return results;
